{"file_text": "@namespace sv_137f27b4935e42bda7566730fe320451.Components.Pages.Application

<div class="step-content">
    <h3>Review & Submit</h3>
    <p>Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="work-review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="description">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="reference-review-item">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <small>@r.Email @(string.IsNullOrEmpty(r.Phone) ? "" : $"| {r.Phone}")</small>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (ErrorMessage != null)
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

<style>
    .review-section {
        border: 1px solid #e9ecef;
        border-radius: 8px;
        padding: 1rem 1.25rem;
        margin-bottom: 1rem;
    }
    .review-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 0.5rem;
    }
    .review-header h4 {
        margin: 0;
        font-size: 1rem;
    }
    .review-section dl {
        display: grid;
        grid-template-columns: 100px 1fr;
        gap: 0.25rem 1rem;
        margin: 0;
    }
    .review-section dt {
        font-weight: 500;
        color: #6c757d;
    }
    .work-review-item, .reference-review-item {
        padding: 0.5rem 0;
        border-bottom: 1px solid #f0f0f0;
    }
    .work-review-item:last-child, .reference-review-item:last-child {
        border-bottom: none;
    }
    .description {
        margin: 0.25rem 0 0;
        color: #555;
        font-size: 0.9rem;
    }
    .cover-letter-preview {
        white-space: pre-wrap;
        background: #f8f9fa;
        padding: 1rem;
        border-radius: 4px;
        font-size: 0.9rem;
    }
</style>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitting { get; set; }
    public bool IsSubmitted { get; set; }
    public int? ApplicationId { get; set; }
    public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;
        StateHasChanged();

        await OnSubmit.InvokeAsync();
    }

    public void SetSubmitted(int id)
    {
        IsSubmitting = false;
        IsSubmitted = true;
        ApplicationId = id;
        StateHasChanged();
    }

    public void SetError(string message)
    {
        IsSubmitting = false;
        ErrorMessage = message;
        StateHasChanged();
    }
}
