@using sv_137f27b4935e42bda7566730fe320451.Services
@namespace sv_137f27b4935e42bda7566730fe320451.Components.Pages.Application

@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator Steps="@_stepNames" CurrentStep="@_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep @ref="_reviewStep"
                        FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnBack="GoBack"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

<style>
    .application-container {
        max-width: 800px;
        margin: 2rem auto;
        padding: 0 1.5rem;
    }
    .application-container h1 {
        margin-bottom: 1.5rem;
    }
    .step-content h3 {
        margin-bottom: 1rem;
        color: #333;
    }
    .step-actions {
        display: flex;
        gap: 0.75rem;
        margin-top: 1.5rem;
        padding-top: 1rem;
        border-top: 1px solid #e9ecef;
    }
    .btn {
        padding: 0.5rem 1.25rem;
        border-radius: 4px;
        border: 1px solid transparent;
        cursor: pointer;
        font-size: 0.9rem;
        text-decoration: none;
    }
    .btn-primary {
        background: #0d6efd;
        color: white;
    }
    .btn-primary:hover {
        background: #0b5ed7;
    }
    .btn-secondary {
        background: #6c757d;
        color: white;
    }
    .btn-success {
        background: #198754;
        color: white;
    }
    .btn-success:hover {
        background: #157347;
    }
    .btn-outline-secondary {
        border-color: #6c757d;
        color: #6c757d;
        background: transparent;
    }
    .btn-outline-danger {
        border-color: #dc3545;
        color: #dc3545;
        background: transparent;
    }
    .btn-link {
        background: none;
        border: none;
        color: #0d6efd;
        cursor: pointer;
        text-decoration: underline;
        padding: 0;
    }
    .btn-lg {
        padding: 0.75rem 2rem;
        font-size: 1rem;
    }
    .btn-sm {
        padding: 0.25rem 0.5rem;
        font-size: 0.8rem;
    }
    .btn:disabled {
        opacity: 0.65;
        cursor: not-allowed;
    }
    .alert {
        padding: 0.75rem 1rem;
        border-radius: 4px;
        margin-top: 1rem;
    }
    .alert-danger {
        background: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
    }
    .alert-success {
        background: #d1e7dd;
        color: #0f5132;
        border: 1px solid #badbcc;
    }
    .field-error {
        color: #dc3545;
        font-size: 0.8rem;
    }
    .is-invalid {
        border-color: #dc3545 !important;
    }
    .text-muted {
        color: #6c757d;
        font-size: 0.9rem;
    }
</style>

@code {
    private int _currentStep = 0;
    private ReviewStep? _reviewStep;

    private readonly List<string> _stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new()
    {
        new WorkEntryModel(string.Empty, string.Empty, DateTime.Today, null, string.Empty, false)
    };

    // Step 3 state
    private List<ReferenceModel> _references = new()
    {
        new ReferenceModel(string.Empty, string.Empty, string.Empty, string.Empty),
        new ReferenceModel(string.Empty, string.Empty, string.Empty, string.Empty)
    };

    // Step 4 state
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
        }
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        _references = refs;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        try
        {
            var workHistory = new WorkHistory(
                _workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.EndDate, e.Description
                )).ToList()
            );

            var references = _references.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone
            )).ToList();

            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                workHistory,
                references,
                _coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            _reviewStep?.SetSubmitted(id);
        }
        catch (Exception ex)
        {
            _reviewStep?.SetError($"Submission failed: {ex.Message}");
        }
    }
}
