@namespace sv_137f27b4935e42bda7566730fe320451.Components.Pages.Application

<div class="step-content">
    <h3>References</h3>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 1)"
                       OnEntryChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (ValidationError != null)
    {
        <div class="alert alert-danger">@ValidationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email))
            {
                ValidationError = "Name, relationship, and email are required for all references.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

