private string StartDateFormatted => Entry.StartDate.ToString("yyyy-MM-dd");
private string EndDateFormatted => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

private void Update(WorkEntryModel updated)
{
    OnEntryChanged.InvokeAsync(updated);
}

private void HandleCompanyChange(ChangeEventArgs e)
{
    Update(Entry with { Company = (string?)e.Value ?? string.Empty });
}

private void HandleTitleChange(ChangeEventArgs e)
{
    Update(Entry with { Title = (string?)e.Value ?? string.Empty });
}

private void HandleStartDateChange(ChangeEventArgs e)
{
    var val = (string?)e.Value;
    if (!string.IsNullOrEmpty(val) && DateTime.TryParse(val, out var date))
    {
        Update(Entry with { StartDate = date });
    }
}

private void HandleEndDateChange(ChangeEventArgs e)
{
    var val = (string?)e.Value;
    DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
    Update(Entry with { EndDate = endDate });
}

private void HandleCurrentChange(ChangeEventArgs e)
{
    var isCurrent = (bool)(e.Value ?? false);
    var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
    OnEntryChanged.InvokeAsync(updated);
}

private void HandleDescriptionChange(ChangeEventArgs e)
{
    Update(Entry with { Description = (string?)e.Value ?? string.Empty });
}

